package com.nivor.project;
import com.nivor.project.dto.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/projects")public class ProjectController{
private final ProjectService service;public ProjectController(ProjectService s){service=s;}@GetMapping public List<ProjectResponse> list(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)Long workspace,@RequestParam(required=false)ProjectStatus status){return service.list(u.getUsername(),workspace,status).stream().map(ProjectResponse::from).toList();}@GetMapping("/{id}")public ProjectResponse get(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return ProjectResponse.from(service.get(u.getUsername(),id));}@PostMapping public ResponseEntity<ProjectResponse> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody ProjectRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ProjectResponse.from(service.create(u.getUsername(),r)));}@PutMapping("/{id}")public ProjectResponse update(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody ProjectRequest r){return ProjectResponse.from(service.update(u.getUsername(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}
}
